scwin.trigger2_onclick = function(e) {
	//debugger;
	var submissionObj = {};
	submissionObj.id = "submission_dynamic";
	submissionObj.action = "submission_requestHeader_WESE-1125_(WSQ-6095).json"; 
	submissionObj.method = "POST";
//submissionObj.mediatype = "text/plain";
	submissionObj.mediatype = "application/json";
	submissionObj.encoding = "UTF-8";
	submissionObj.mode = "synchronous";
	submissionObj.requestHeader =  {"token": "bbb"};
	submissionObj.processMsg = "처리중입니다";

	//submission 생성
	$p.createSubmission(submissionObj);

	// 동적 서브미션 헤더 세팅
	var subObj = $p.getSubmission("submission_dynamic");
	subObj.setRequestHeader("test", "aaa");

	$p.executeSubmission("submission_dynamic");
};
